import {experience} from './scene.js';
let context,master,analyser,data,timer,step=0,on=false,toastTimeout;const soundButtons=[document.querySelector('.sound-toggle'),document.querySelector('#audio-status')];
function toast(message){const el=document.querySelector('.toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove('show'),3200)}
function note(freq,duration,delay=0,volume=.07,type='sine'){const t=context.currentTime+delay,o=context.createOscillator(),g=context.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(volume,t+.08);g.gain.exponentialRampToValueAtTime(.0001,t+duration);o.connect(g);g.connect(master);o.start(t);o.stop(t+duration+.04);o.onended=()=>{o.disconnect();g.disconnect()}}
function sequence(){const chords=[[130.81,164.81,196],[110,130.81,164.81],[87.31,130.81,174.61],[98,146.83,196]],melody=[523.25,392,329.63,293.66,440,329.63,261.63,392];if(step%4===0){chords[Math.floor(step/4)%4].forEach((f,i)=>note(f,5,i*.12,.065));note(chords[Math.floor(step/4)%4][0]/2,3,0,.09)}note(melody[step%8],2.7,0,.085);note(melody[(step+2)%8]*2,1.8,.45,.018);step++}
async function toggleSound(){try{if(!context){context=new(window.AudioContext||window.webkitAudioContext)();master=context.createGain();master.gain.value=0;analyser=context.createAnalyser();analyser.fftSize=256;data=new Uint8Array(analyser.frequencyBinCount);master.connect(analyser);analyser.connect(context.destination)}await context.resume();on=!on;master.gain.cancelScheduledValues(context.currentTime);master.gain.setTargetAtTime(on?.65:0,context.currentTime,.3);clearInterval(timer);if(on){sequence();timer=setInterval(sequence,940);toast('声场已开启 · 戴上耳机，慢慢沉醉')}experience.soundOn=on;sync();}catch{toast('声音暂时无法开启，请检查浏览器音频设置')}}
function sync(){document.body.classList.toggle('sound-on',on);soundButtons.forEach(b=>b.setAttribute('aria-pressed',String(on)));soundButtons[0].setAttribute('aria-label',on?'关闭环境音乐':'开启环境音乐');document.querySelector('.sound-label').textContent=on?'声音已开启':'开启声音';document.querySelector('#listen-label').textContent=on?'让声音，安静一会':'先听听，这个宇宙';document.querySelector('#status-text').textContent=on?'沉浸声场 · 正在流动':'声场静候唤醒';}
soundButtons.forEach(b=>b.addEventListener('click',toggleSound));document.querySelector('#listen').addEventListener('click',toggleSound);
function readSound(){if(on&&analyser&&!document.hidden){analyser.getByteFrequencyData(data);let sum=0;for(let i=0;i<24;i++)sum+=data[i];experience.energy+=(sum/(24*255)-experience.energy)*.12}else experience.energy*=.95;requestAnimationFrame(readSound)}readSound();
document.addEventListener('visibilitychange',()=>{if(!context)return;if(document.hidden){clearInterval(timer);context.suspend()}else if(on){context.resume();sequence();timer=setInterval(sequence,940)}});
document.querySelector('#fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{toast('当前浏览器不支持全屏，可在独立浏览器打开体验')}});document.addEventListener('fullscreenchange',()=>{const b=document.querySelector('#fullscreen');b.setAttribute('aria-label',document.fullscreenElement?'退出全屏':'进入全屏');b.title=document.fullscreenElement?'退出全屏':'进入全屏'});
const dialog=document.querySelector('#info-dialog');let previousFocus;
function showInfo(type){previousFocus=document.activeElement;document.querySelector('#dialog-title').textContent=type==='guide'?'潜入之前':'靡靡之音。';document.querySelector('#dialog-content').innerHTML=type==='guide'?'<p>在一片会呼吸的音乐海洋里，从微小细胞开始。吞噬比你弱小的生命，避开天敌，在成长中选择自己的进化方向。</p><div class="guide-keys"><kbd>W A S D / 方向键</kbd> 移动<br><kbd>Space</kbd> 冲刺 · <kbd>E</kbd> 进化主动技能<br><kbd>Esc / P</kbd> 暂停 · <kbd>M</kbd> 切换声音<br>手机上使用摇杆移动，点击技能按钮。</div><p>音乐随你的生命阶段变化。戴上耳机，听见自己的成长。</p><a class="primary" href="symphony/">准备好了，即刻潜入 ↗</a>':'<p>有些声音，让人不想离开。<br>有些世界，值得把时间忘掉。</p><p>靡靡之音，是一个关于音乐与游戏的小小宇宙。<br>我们相信，音乐可以触碰，旋律可以探索，<br>而一场好游戏，本身就是一首动人的交响曲。</p><p>此刻的第一颗星球：吞噬交响曲。<br>愿你在这里，尽情沉醉。</p>';dialog.showModal()}
document.querySelector('#about-button').addEventListener('click',()=>showInfo('about'));document.querySelector('#guide-button').addEventListener('click',()=>showInfo('guide'));document.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>previousFocus?.focus());dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()});
